def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        return value.isoformat()
    except AttributeError:
        # If value doesn't have isoformat, try to convert to string
        return str(value)
    except Exception as e:
        raise ValueError(f"Failed to dehydrate time value: {e}")
