def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        # Get the manifest from the application spec
        manifest = app.spec.manifest

        # Initialize the observer schema if not already present
        if not hasattr(app.spec, 'observer_schema') or app.spec.observer_schema is None:
            app.spec.observer_schema = {}

        # Iterate through each resource in the manifest
        for resource_name, resource in manifest.items():
            # Check if a custom observer schema is already specified for this resource
            if resource_name not in app.spec.observer_schema:
                # Generate a default observer schema for this resource
                # The default schema typically includes basic fields like status, conditions, etc.
                default_schema = {
                    "status": {
                        "type": "object",
                        "properties": {
                            "phase": {
                                "type": "string"
                            },
                            "conditions": {
                                "type": "array",
                                "items": {
                                    "type": "object",
                                    "properties": {
                                        "type": {
                                            "type": "string"
                                        },
                                        "status": {
                                            "type": "string"
                                        },
                                        "reason": {
                                            "type": "string"
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                app.spec.observer_schema[resource_name] = default_schema
    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {str(e)}")
