    def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Collect all digests from manifest files
        manifest_digests = set()
        for manifest_file in manifest_files:
            if hasattr(manifest_file, 'digests'):
                manifest_digests.update(manifest_file.digests)
            elif isinstance(manifest_file, dict):
                # Assume dict has a 'digests' key
                if 'digests' in manifest_file:
                    manifest_digests.update(manifest_file['digests'])
            elif isinstance(manifest_file, (list, tuple)):
                manifest_digests.update(manifest_file)
            else:
                # If it's a single digest
                manifest_digests.add(manifest_file)

        # Check that all digests used are present in manifest
        missing_digests = digests_used - manifest_digests
        if missing_digests:
            raise ValueError(f"Digests used but not present in manifest: {missing_digests}")

        # Check that all digests in manifest are used (if needed)
        # The docstring says "that are needed are present and used"
        # This implies we should check that all manifest digests are used
        unused_digests = manifest_digests - digests_used
        if unused_digests:
            raise ValueError(f"Digests present in manifest but not used: {unused_digests}")

        return True
