def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if version not in inventory:
        raise ValueError(f"version {version} not found in inventory")

    version_data = inventory[version]
    if not isinstance(version_data, dict):
        raise TypeError(f"inventory[{version}] must be a dictionary")

    # Assuming version_data has a structure that maps logical paths to content files
    # For example: {logical_path: [content_file1, content_file2, ...]}
    # Or it might be a list of entries with logical_path and content_files

    logical_path_map = {}

    # Try to handle different possible structures
    if isinstance(version_data, dict):
        for logical_path, content_files in version_data.items():
            if isinstance(content_files, (list, tuple, set)):
                logical_path_map[logical_path] = set(content_files)
            elif isinstance(content_files, str):
                logical_path_map[logical_path] = {content_files}
            else:
                # If content_files is not a collection, treat it as a single file
                logical_path_map[logical_path] = {content_files}
    elif isinstance(version_data, (list, tuple)):
        # Assume it's a list of dictionaries with 'logical_path' and 'content_files' keys
        for entry in version_data:
            if isinstance(entry, dict):
                logical_path = entry.get('logical_path')
                content_files = entry.get('content_files', [])
                if logical_path is not None:
                    if isinstance(content_files, (list, tuple, set)):
                        logical_path_map[logical_path] = set(content_files)
                    elif isinstance(content_files, str):
                        logical_path_map[logical_path] = {content_files}
                    else:
                        logical_path_map[logical_path] = {content_files}

    return logical_path_map
