def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os
    import sys

    # If commands is a string, split it into a list
    if isinstance(commands, str):
        commands = commands.split()

    # Combine commands and args
    full_command = commands + args

    # Set up environment
    if env is None:
        env = os.environ.copy()
    else:
        env = os.environ.copy()
        env.update(env)

    # Set up stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    # Run the command
    try:
        if verbose:
            print("Running command:", " ".join(full_command))

        result = subprocess.run(
            full_command,
            cwd=cwd,
            env=env,
            stderr=stderr,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if not hide_stderr else None,
            check=True
        )

        if verbose:
            print("Command completed successfully.")

        return result
    except subprocess.CalledProcessError as e:
        if verbose:
            print("Command failed with return code:", e.returncode)
            if e.stderr:
                print("Stderr:", e.stderr.decode())
        raise
    except FileNotFoundError:
        if verbose:
            print("Command not found:", full_command[0])
        raise
    except Exception as e:
        if verbose:
            print("Error running command:", str(e))
        raise
