import re
import sys
import shlex

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1

    if platform == 1:
        # POSIX-like splitting
        # Use shlex.split for POSIX
        try:
            return shlex.split(s)
        except ValueError:
            # If shlex fails, fall back to a regex-based approach
            # This handles cases where shlex might be too strict
            # For POSIX, we can use a regex that handles quotes and escapes
            # But for simplicity and robustness, let's use a more permissive approach
            # Actually, let's just use shlex.split with posix=True
            return shlex.split(s, posix=True)
    elif platform == 0:
        # Windows/CMD splitting
        # Windows command line parsing is different
        # We need to handle quotes and escapes differently
        # For Windows, we can use a regex-based approach
        # The Windows command line parser treats quotes specially
        # Let's implement a simple Windows-style splitter

        result = []
        current = []
        in_quotes = False
        escape_next = False
        i = 0
        while i < len(s):
            c = s[i]
            if escape_next:
                current.append(c)
                escape_next = False
            elif c == '\\':
                # Check if next char is a quote or backslash
                if i + 1 < len(s) and s[i+1] in ('"', '\\'):
                    escape_next = True
                    i += 1
                else:
                    current.append(c)
            elif c == '"':
                in_quotes = not in_quotes
            elif c in (' ', '\t') and not in_quotes:
                if current:
                    result.append(''.join(current))
                    current = []
            else:
                current.append(c)
            i += 1
        if current:
            result.append(''.join(current))
        return result
    else:
        raise ValueError(f"Invalid platform value: {platform}")

