def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET
    from typing import Dict

    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except (json.JSONDecodeError, ValueError):
        pass

    # Try XRD (XML)
    try:
        root = ET.fromstring(document)
        result = {}

        # XRD structure: <XRD xmlns="http://docs.oasis-open.org/webfinger/xrd/1.0">
        # <subject>...</subject>
        # <alias>...</alias>
        # <link rel="..." href="..." type="..."/>

        # Get subject
        subject_elem = root.find('.//{http://docs.oasis-open.org/webfinger/xrd/1.0}subject')
        if subject_elem is not None and subject_elem.text:
            result['subject'] = subject_elem.text.strip()

        # Get aliases
        aliases = []
        for alias_elem in root.findall('.//{http://docs.oasis-open.org/webfinger/xrd/1.0}alias'):
            if alias_elem.text:
                aliases.append(alias_elem.text.strip())
        if aliases:
            result['aliases'] = aliases

        # Get links
        links = []
        for link_elem in root.findall('.//{http://docs.oasis-open.org/webfinger/xrd/1.0}link'):
            link = {}
            rel = link_elem.get('rel')
            href = link_elem.get('href')
            link_type = link_elem.get('type')
            if rel:
                link['rel'] = rel
            if href:
                link['href'] = href
            if link_type:
                link['type'] = link_type
            links.append(link)
        if links:
            result['links'] = links

        return result
    except ET.ParseError:
        pass

    # If neither JSON nor XRD, return empty dict or raise
    return {}
