def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import requests
    from xml.etree import ElementTree
    import re

    # Construct the URL for the host-meta document
    url = f"https://{host}/.well-known/host-meta"

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise Exception(f"Failed to retrieve host-meta document from {host}: {e}")

    # Parse the XML response
    try:
        root = ElementTree.fromstring(response.content)
    except ElementTree.ParseError as e:
        raise Exception(f"Failed to parse XML response from {host}: {e}")

    # Create a simple XRD-like structure
    class XRD:
        def __init__(self, root):
            self.root = root
            self.links = []
            self.parse()

        def parse(self):
            # Handle both XRD and XRDS namespaces
            for link in self.root.iter():
                if link.tag.endswith('Link'):
                    rel = link.get('rel')
                    href = link.get('href')
                    if rel and href:
                        self.links.append({'rel': rel, 'href': href})

    return XRD(root)
