    def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        if not isinstance(parser_dict, dict):
            raise TypeError("parser_dict must be a dictionary")

        include_key = "include"
        if include_key not in parser_dict:
            return parser_dict

        include_value = parser_dict[include_key]

        if not isinstance(include_value, (list, tuple)):
            raise ValueError("The 'include' directive must be a list or tuple of group names")

        # Assuming there is a method or attribute to get the groups
        # This is a placeholder; in a real implementation, this would depend on the class structure
        # For example, self._groups might be a dict mapping group names to their definitions
        # We'll assume self._groups exists and is a dict

        if not hasattr(self, '_groups'):
            raise AttributeError("The object does not have a '_groups' attribute")

        resolved_groups = {}
        for group_name in include_value:
            if not isinstance(group_name, str):
                raise ValueError(f"Group name must be a string, got {type(group_name)}")
            if group_name not in self._groups:
                raise KeyError(f"Group '{group_name}' not found in available groups")
            resolved_groups[group_name] = self._groups[group_name]

        # Remove the include key and add the resolved groups
        new_parser_dict = {k: v for k, v in parser_dict.items() if k != include_key}
        new_parser_dict.update(resolved_groups)

        return new_parser_dict
