    def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required_args = []
        for option in options_spec:
            if not isinstance(option, dict):
                continue
            required_when = option.get('required_when')
            if required_when is None:
                continue
            # Check if the condition is met
            if self._check_required_when_condition(required_when, args):
                arg_name = option.get('name')
                if arg_name:
                    required_args.append(arg_name)
        return required_args

    def _check_required_when_condition(self, condition, args):
        """Check if the required_when condition is met.

        :param condition: the condition to check
        :param args: the received input arguments
        :return: bool, True if condition is met, False otherwise
        """
        if isinstance(condition, dict):
            # Handle complex conditions like {'arg': 'value'}
            for key, value in condition.items():
                if key not in args:
                    return False
                if args[key] != value:
                    return False
            return True
        elif isinstance(condition, list):
            # Handle list of conditions (any of them can be true)
            for cond in condition:
                if self._check_required_when_condition(cond, args):
                    return True
            return False
        elif isinstance(condition, str):
            # Simple condition: check if the argument is present
            return condition in args
        else:
            # Unknown condition type, assume not met
            return False
