def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import yaml

    spec_file = os.path.join(plugin_dir, 'plugin.yaml')
    if not os.path.exists(spec_file):
        spec_file = os.path.join(plugin_dir, 'plugin.json')

    if not os.path.exists(spec_file):
        raise FileNotFoundError(f"Plugin spec file not found in {plugin_dir}")

    try:
        with open(spec_file, 'r') as f:
            if spec_file.endswith('.yaml') or spec_file.endswith('.yml'):
                spec = yaml.safe_load(f)
            else:
                spec = json.load(f)
    except Exception as e:
        raise ValueError(f"Error reading plugin spec file: {e}")

    if not isinstance(spec, dict):
        raise ValueError("Plugin spec must be a dictionary")

    def flatten_dict(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            elif isinstance(v, list):
                for i, item in enumerate(v):
                    if isinstance(item, dict):
                        items.extend(flatten_dict(item, f"{new_key}[{i}]", sep=sep).items())
                    else:
                        items.append((f"{new_key}[{i}]", item))
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec)
```

